INSERT INTO regulations (id, title, formal_title, summary, description, full_description, region, category, status, effective_date, source_name, source_url, tags) VALUES ('0ea15267-2e45-5125-a550-9ab847bb4b9f', 'TCFD Use of Scenario Analysis in Disclosure of Climate-Related', 'The Use of Scenario Analysis in Disclosure of Climate-Related Risks and Opportunities', 'The Technical Supplement advises companies on conducting climate-related scenario analysis, a fundamental TCFD recommendation that helps companies plan for resilience', 'The Technical Supplement advises companies on conducting climate-related scenario analysis, a fundamental TCFD recommendation that helps companies plan for resilience', 'The Technical Supplement advises companies on conducting climate-related scenario analysis, a fundamental TCFD recommendation that helps companies plan for resilience', 'TCFD', 'climate', 'in_force', '2017-01-01'::date, 'Task Force on Climate-Related Financial Disclosures (TCFD)', 'https://www.carrotsandsticks.org/policies/327_4', ARRAY['guidance_frameworks', 'sdg13', 'mandatory', 'tcfd', 'disclosure']::text[]) ON CONFLICT (id) DO NOTHING;
INSERT INTO regulations (id, title, formal_title, summary, description, full_description, region, category, status, effective_date, source_name, source_url, tags) VALUES ('215d9afd-33e4-5b0e-b774-52be732068d3', 'TCFD Implementing the Recommendations of the Task Force', 'Implementing the Recommendations of the Task Force on Climate-related Financial Disclosures', 'This report aims to provide guidance on how to implement the recommendations of the Task Force on climate-related financial disclosures.', 'This report aims to provide guidance on how to implement the recommendations of the Task Force on climate-related financial disclosures.', 'This report aims to provide guidance on how to implement the recommendations of the Task Force on climate-related financial disclosures.', 'TCFD', 'climate', 'in_force', '2017-01-01'::date, 'Task Force on Climate-Related Financial Disclosures (TCFD)', 'https://www.carrotsandsticks.org/policies/327_5', ARRAY['guidance_frameworks', 'sdg13', 'tcfd', 'disclosure', 'voluntary']::text[]) ON CONFLICT (id) DO NOTHING;
INSERT INTO regulations (id, title, formal_title, summary, description, full_description, region, category, status, effective_date, source_name, source_url, tags) VALUES ('8f4ad454-ad71-5f22-8c70-bcca5a226f29', 'TNFD Recommendations of the Taskforce on Nature-related Financial Disclosures', 'Recommendations of the Taskforce on Nature-related Financial Disclosures', 'The Taskforce on Nature-related Financial Disclosures (TNFD) provides a comprehensive framework to support businesses and financial institutions in identifying, assessing, managing, and disclosing their nature-related risks, dependencies, impacts, and opportunities. Published in September 2023, the TNFD recommendations aim to integrate nature into mainstream risk management and corporate reporting, mirroring the structure of the Taskforce on Climate-related Financial Disclosures (TCFD). The document outlines 14 recommended disclosures structured under four pillars: Governance, Strategy, Risk and Impact Management, and Metrics and Targets. The guidance emphasizes the urgent need to address nature loss, highlighting its systemic financial risks and interconnection with climate challenges. The TNFD also aligns with global sustainability goals such as the Kunming-Montreal Global Biodiversity Framework (GBF), facilitating voluntary adoption and integration into regulatory standards. By adopting the TNFD framework, organizations can enhance transparency, drive sustainable practices, and mitigate financial risks associated with nature loss.', 'The Taskforce on Nature-related Financial Disclosures (TNFD) provides a comprehensive framework to support businesses and financial institutions in identifying, assessing, managing, and disclosing their nature-related risks, dependencies, impacts, and opportunities. Published in September 2023, the TNFD recommendations aim to integrate nature into mainstream risk management and corporate reporting, mirroring the structure of the Taskforce on Climate-related Financial Disclosures (TCFD). The document outlines 14 recommended disclosures structured under four pillars: Governance, Strategy, Risk and Impact Management, and Metrics and Targets. The guidance emphasizes the urgent need to address nature loss, highlighting its systemic financial risks and interconnection with climate challenges. The TNFD also aligns with global sustainability goals such as the Kunming-Montreal Global Biodiversity Framework (GBF), facilitating voluntary adoption and integration into regulatory standards. By adopting the TNFD framework, organizations can enhance transparency, drive sustainable practices, and mitigate financial risks associated with nature loss.', 'The Taskforce on Nature-related Financial Disclosures (TNFD) provides a comprehensive framework to support businesses and financial institutions in identifying, assessing, managing, and disclosing their nature-related risks, dependencies, impacts, and opportunities. Published in September 2023, the TNFD recommendations aim to integrate nature into mainstream risk management and corporate reporting, mirroring the structure of the Taskforce on Climate-related Financial Disclosures (TCFD). The document outlines 14 recommended disclosures structured under four pillars: Governance, Strategy, Risk and Impact Management, and Metrics and Targets. The guidance emphasizes the urgent need to address nature loss, highlighting its systemic financial risks and interconnection with climate challenges. The TNFD also aligns with global sustainability goals such as the Kunming-Montreal Global Biodiversity Framework (GBF), facilitating voluntary adoption and integration into regulatory standards. By adopting the TNFD framework, organizations can enhance transparency, drive sustainable practices, and mitigate financial risks associated with nature loss.', 'TNFD', 'climate', 'in_force', '2023-01-01'::date, 'Taskforce on Nature-related Financial Disclosures (TNFD)', 'https://www.carrotsandsticks.org/policies/380_1', ARRAY['guidance_frameworks', 'sdg13', 'sdg9', 'sdg7', 'sdg16', 'sdg12', 'disclosure', 'sdg15', 'voluntary', 'tnfd']::text[]) ON CONFLICT (id) DO NOTHING;
INSERT INTO regulations (id, title, formal_title, summary, description, full_description, region, category, status, effective_date, source_name, source_url, tags) VALUES ('23583f0c-2e89-5f70-86f8-fd4c0099a650', 'Thailand Taxonomy Phase 1 June', 'Thailand Taxonomy Phase 1 June 2023', 'This taxonomy serves as a versatile tool to guide investments towards sustainability, harmonize data disclosure, assess environmental risks, and support compliance with global standards, thereby attracting international capital and aiding in the implementation of state policies for GHG emission reduction.', 'This taxonomy serves as a versatile tool to guide investments towards sustainability, harmonize data disclosure, assess environmental risks, and support compliance with global standards, thereby attracting international capital and aiding in the implementation of state policies for GHG emission reduction.', 'This taxonomy serves as a versatile tool to guide investments towards sustainability, harmonize data disclosure, assess environmental risks, and support compliance with global standards, thereby attracting international capital and aiding in the implementation of state policies for GHG emission reduction.', 'Thailand', 'climate', 'in_force', '2023-01-01'::date, 'Thailand', 'https://www.carrotsandsticks.org/policies/177_28', ARRAY['sdg13', 'thailand', 'mandatory', 'mandatory_regulations', 'disclosure', 'sdg15']::text[]) ON CONFLICT (id) DO NOTHING;
INSERT INTO regulations (id, title, formal_title, summary, description, full_description, region, category, status, effective_date, source_name, source_url, tags) VALUES ('27b9c1c8-9fc4-5948-89d9-226e8e84ae7d', 'Thailand SDG Guidebook for Thai Listed Companies', 'SDG Guidebook for Thai Listed Companies, 2023', 'Unveiled in 2023, Thailand''s SET and UNDP SDG Guidebook empowers listed companies to integrate Sustainable Development Goals (SDGs) into their core strategies. Aligning business operations with environmental and social goals, it offers practical guidance on identifying relevant priorities, setting impactful goals, and measuring progress. This framework aims to boost sustainability performance, strengthen stakeholder engagement, and unlock new business opportunities, driving Thailand''s economic and social advancement through the lens of the SDGs.', 'Unveiled in 2023, Thailand''s SET and UNDP SDG Guidebook empowers listed companies to integrate Sustainable Development Goals (SDGs) into their core strategies. Aligning business operations with environmental and social goals, it offers practical guidance on identifying relevant priorities, setting impactful goals, and measuring progress. This framework aims to boost sustainability performance, strengthen stakeholder engagement, and unlock new business opportunities, driving Thailand''s economic and social advancement through the lens of the SDGs.', 'Unveiled in 2023, Thailand''s SET and UNDP SDG Guidebook empowers listed companies to integrate Sustainable Development Goals (SDGs) into their core strategies. Aligning business operations with environmental and social goals, it offers practical guidance on identifying relevant priorities, setting impactful goals, and measuring progress. This framework aims to boost sustainability performance, strengthen stakeholder engagement, and unlock new business opportunities, driving Thailand''s economic and social advancement through the lens of the SDGs.', 'Thailand', 'climate', 'in_force', '2023-01-01'::date, 'Thailand', 'https://www.carrotsandsticks.org/policies/177_30', ARRAY['thailand', 'regulations', 'sdg17', 'mandatory', 'disclosure', 'sdg15']::text[]) ON CONFLICT (id) DO NOTHING;
INSERT INTO regulations (id, title, formal_title, summary, description, full_description, region, category, status, effective_date, source_name, source_url, tags) VALUES ('0b61490e-4d31-508c-b8a3-5d89111efa6a', 'Thailand Sustainability Reporting Guide for Listed Companies', 'Sustainability Reporting Guide for Listed Companies, 2022', 'The Thailand Securities and Exchange Commission (SEC) issued a sustainability reporting guide in 2021 for companies listed on the Stock Exchange of Thailand (SET). The guide provides information on the reporting of sustainability practices and is aimed at promoting environmental, social, and governance (ESG) transparency. It covers reporting requirements, including governance structures, policies, and practices, and recommends a "comply or explain" approach. The guide also provides guidance on the selection of ESG indicators and the process of reporting. Companies are encouraged to use the guide to improve their sustainability performance and disclosure, and the SEC has stated that it will monitor compliance with the guidelines.', 'The Thailand Securities and Exchange Commission (SEC) issued a sustainability reporting guide in 2021 for companies listed on the Stock Exchange of Thailand (SET). The guide provides information on the reporting of sustainability practices and is aimed at promoting environmental, social, and governance (ESG) transparency. It covers reporting requirements, including governance structures, policies, and practices, and recommends a "comply or explain" approach. The guide also provides guidance on the selection of ESG indicators and the process of reporting. Companies are encouraged to use the guide to improve their sustainability performance and disclosure, and the SEC has stated that it will monitor compliance with the guidelines.', 'The Thailand Securities and Exchange Commission (SEC) issued a sustainability reporting guide in 2021 for companies listed on the Stock Exchange of Thailand (SET). The guide provides information on the reporting of sustainability practices and is aimed at promoting environmental, social, and governance (ESG) transparency. It covers reporting requirements, including governance structures, policies, and practices, and recommends a "comply or explain" approach. The guide also provides guidance on the selection of ESG indicators and the process of reporting. Companies are encouraged to use the guide to improve their sustainability performance and disclosure, and the SEC has stated that it will monitor compliance with the guidelines.', 'Thailand', 'climate', 'in_force', '2022-01-01'::date, 'Thailand', 'https://www.carrotsandsticks.org/policies/177_18', ARRAY['thailand', 'mandatory', 'sdg16', 'mandatory_regulations', 'disclosure', 'sdg15']::text[]) ON CONFLICT (id) DO NOTHING;
