INSERT INTO regulations (id, title, formal_title, summary, description, full_description, region, category, status, effective_date, source_name, source_url, tags) VALUES ('b2b9756c-6463-5c23-8710-057ed026dd02', 'Thailand Corporate sustainability guide for listed companies', 'Corporate sustainability guide for listed companies, 2022', 'The SET''s 2022 Corporate Sustainability Guide equips Thai listed companies to navigate sustainable practices. Offering practical advice on strategy, disclosure, and reporting, it aligns with global standards and Thailand''s SDGs. It encourages environmental initiatives, social responsibility, and good governance, aiming to create a sustainable Thai capital market and enhance companies'' long-term value.', 'The SET''s 2022 Corporate Sustainability Guide equips Thai listed companies to navigate sustainable practices. Offering practical advice on strategy, disclosure, and reporting, it aligns with global standards and Thailand''s SDGs. It encourages environmental initiatives, social responsibility, and good governance, aiming to create a sustainable Thai capital market and enhance companies'' long-term value.', 'The SET''s 2022 Corporate Sustainability Guide equips Thai listed companies to navigate sustainable practices. Offering practical advice on strategy, disclosure, and reporting, it aligns with global standards and Thailand''s SDGs. It encourages environmental initiatives, social responsibility, and good governance, aiming to create a sustainable Thai capital market and enhance companies'' long-term value.', 'Thailand', 'climate', 'in_force', '2022-01-01'::date, 'Thailand', 'https://www.carrotsandsticks.org/policies/177_29', ARRAY['thailand', 'regulations', 'mandatory', 'sdg16', 'disclosure', 'sdg15']::text[]) ON CONFLICT (id) DO NOTHING;
INSERT INTO regulations (id, title, formal_title, summary, description, full_description, region, category, status, effective_date, source_name, source_url, tags) VALUES ('b889170a-235b-5d40-8385-0ec6e2f05b0d', 'Thailand Thai Labour Standard TLS 8001. Labour Corporate Social', 'Thai Labour Standard TLS 8001. Labour Corporate Social Responsibility: Requirements', 'The purpose of these requirements is to provide labour treatment norms that demonstrate labour-related social responsibility of Thai businesses.', 'The purpose of these requirements is to provide labour treatment norms that demonstrate labour-related social responsibility of Thai businesses.', 'The purpose of these requirements is to provide labour treatment norms that demonstrate labour-related social responsibility of Thai businesses.', 'Thailand', 'social', 'in_force', '2020-01-01'::date, 'Thailand', 'https://www.carrotsandsticks.org/policies/177_17', ARRAY['sdg8', 'thailand', 'other sustainability policy', 'voluntary', 'voluntary_frameworks']::text[]) ON CONFLICT (id) DO NOTHING;
INSERT INTO regulations (id, title, formal_title, summary, description, full_description, region, category, status, effective_date, source_name, source_url, tags) VALUES ('5f28aab1-ed05-5f53-b69f-9133b890e9bc', 'Thailand FORM 56-1 One Report (Attached to Notification No', 'FORM 56-1 One Report (Attached to Notification No. Tor Jor. 55/2563)', 'FORM 56-1 One Report is a set of guidelines issued by the Stock Exchange of Thailand (SET) in 2021, which aims to promote sustainability reporting by listed companies. The guidelines require companies to prepare an annual sustainability report that covers environmental, social, and governance (ESG) aspects of their operations and performance. The report should follow a standardized format and provide relevant and reliable information to investors, stakeholders, and the public. The guidelines are not mandatory, but companies are encouraged to adopt them to enhance transparency and accountability. The guidelines are attached to Notification No. Tor Jor. 55/2563.', 'FORM 56-1 One Report is a set of guidelines issued by the Stock Exchange of Thailand (SET) in 2021, which aims to promote sustainability reporting by listed companies. The guidelines require companies to prepare an annual sustainability report that covers environmental, social, and governance (ESG) aspects of their operations and performance. The report should follow a standardized format and provide relevant and reliable information to investors, stakeholders, and the public. The guidelines are not mandatory, but companies are encouraged to adopt them to enhance transparency and accountability. The guidelines are attached to Notification No. Tor Jor. 55/2563.', 'FORM 56-1 One Report is a set of guidelines issued by the Stock Exchange of Thailand (SET) in 2021, which aims to promote sustainability reporting by listed companies. The guidelines require companies to prepare an annual sustainability report that covers environmental, social, and governance (ESG) aspects of their operations and performance. The report should follow a standardized format and provide relevant and reliable information to investors, stakeholders, and the public. The guidelines are not mandatory, but companies are encouraged to adopt them to enhance transparency and accountability. The guidelines are attached to Notification No. Tor Jor. 55/2563.', 'Thailand', 'climate', 'in_force', '2019-01-01'::date, 'Thailand', 'https://www.carrotsandsticks.org/policies/177_19', ARRAY['thailand', 'mandatory', 'sdg16', 'mandatory_regulations', 'disclosure', 'sdg15']::text[]) ON CONFLICT (id) DO NOTHING;
INSERT INTO regulations (id, title, formal_title, summary, description, full_description, region, category, status, effective_date, source_name, source_url, tags) VALUES ('782297b7-9eb0-5f32-8d32-5ac949d72f44', 'Thailand Thai Corporate Governance Code for Listed Companies', 'Thai Corporate Governance Code for Listed Companies, 2017', 'This Corporate Governance Code (the “CG Code”) is therefore developed as practice principles for the board of directors, as the leader and governing body of a listed company, to fulfil all of those expectations. The Principles of this CG Code integrate the essence of principles and best practices of the G20/OECD Principles of Corporate Governance, the Stock Exchange of Thailand Principles of Good Corporate Governance, principles of social and environment responsibilities for business, as well as the business leadership concept, and delineated as the board’s roles and responsibilities for the company’s long-term sustainable value creation. In this regard, the value created should not only be good for the company but also for its shareholders, stakeholders, the capital market and the society at large. If practiced in substance, the objective of long-term sustainable value creation should be reflected in the company’s business model, and ingrained in its corporate culture to ensure company-wide practices.', 'This Corporate Governance Code (the “CG Code”) is therefore developed as practice principles for the board of directors, as the leader and governing body of a listed company, to fulfil all of those expectations. The Principles of this CG Code integrate the essence of principles and best practices of the G20/OECD Principles of Corporate Governance, the Stock Exchange of Thailand Principles of Good Corporate Governance, principles of social and environment responsibilities for business, as well as the business leadership concept, and delineated as the board’s roles and responsibilities for the company’s long-term sustainable value creation. In this regard, the value created should not only be good for the company but also for its shareholders, stakeholders, the capital market and the society at large. If practiced in substance, the objective of long-term sustainable value creation should be reflected in the company’s business model, and ingrained in its corporate culture to ensure company-wide practices.', 'This Corporate Governance Code (the “CG Code”) is therefore developed as practice principles for the board of directors, as the leader and governing body of a listed company, to fulfil all of those expectations. The Principles of this CG Code integrate the essence of principles and best practices of the G20/OECD Principles of Corporate Governance, the Stock Exchange of Thailand Principles of Good Corporate Governance, principles of social and environment responsibilities for business, as well as the business leadership concept, and delineated as the board’s roles and responsibilities for the company’s long-term sustainable value creation. In this regard, the value created should not only be good for the company but also for its shareholders, stakeholders, the capital market and the society at large. If practiced in substance, the objective of long-term sustainable value creation should be reflected in the company’s business model, and ingrained in its corporate culture to ensure company-wide practices.', 'Thailand', 'nature', 'in_force', '2017-01-01'::date, 'Thailand', 'https://www.carrotsandsticks.org/policies/177_7', ARRAY['thailand', 'regulations', 'mandatory', 'sdg16', 'disclosure', 'sdg15']::text[]) ON CONFLICT (id) DO NOTHING;
INSERT INTO regulations (id, title, formal_title, summary, description, full_description, region, category, status, effective_date, source_name, source_url, tags) VALUES ('7da36226-9d28-5ce7-ad46-c58884f170ff', 'Thailand Investment Governance Code for Institutional Investors (I Code)', 'Investment Governance Code for Institutional Investors (I Code), 2017', 'This Code contains investment governance principles and guidance reflecting current international standards and best practices for responsible and effective stewardship over investments by Institutional Investors. Implementation of the Code by Institutional Investors will enhance confidence by domestic and global markets clients and trust that investment decisions and management are done in their best interest. Moreover, the Code promotes and contributes to a good corporate governance ecosystem, stimulates responsible and sustainable practices by listed companies, and fosters growth and development of the Thai capital market and the wider economy.', 'This Code contains investment governance principles and guidance reflecting current international standards and best practices for responsible and effective stewardship over investments by Institutional Investors. Implementation of the Code by Institutional Investors will enhance confidence by domestic and global markets clients and trust that investment decisions and management are done in their best interest. Moreover, the Code promotes and contributes to a good corporate governance ecosystem, stimulates responsible and sustainable practices by listed companies, and fosters growth and development of the Thai capital market and the wider economy.', 'This Code contains investment governance principles and guidance reflecting current international standards and best practices for responsible and effective stewardship over investments by Institutional Investors. Implementation of the Code by Institutional Investors will enhance confidence by domestic and global markets clients and trust that investment decisions and management are done in their best interest. Moreover, the Code promotes and contributes to a good corporate governance ecosystem, stimulates responsible and sustainable practices by listed companies, and fosters growth and development of the Thai capital market and the wider economy.', 'Thailand', 'nature', 'in_force', '2017-01-01'::date, 'Thailand', 'https://www.carrotsandsticks.org/policies/177_8', ARRAY['thailand', 'regulations', 'mandatory', 'sdg16', 'disclosure', 'sdg15']::text[]) ON CONFLICT (id) DO NOTHING;
INSERT INTO regulations (id, title, formal_title, summary, description, full_description, region, category, status, effective_date, source_name, source_url, tags) VALUES ('6e60158e-305c-51cb-866c-c56239101fa5', 'Thailand Notification of the Capital Market Supervisory Board No', 'Notification of the Capital Market Supervisory Board No. TorChor. 44/2556 Re: Rules, Conditions and Procedures for Disclosure regarding Financial and Non-financial Information of Securities Issuers', 'The Capital Market Supervisory Board of the Kingdom of Thailand has issued the following regulations by virtue of section 16/6 and Section 89/27 of the Securities and Exchange Act B.E. 2535 (1992). The following Notifications are to come into effect from 1 January 2014. The securities issuer under Section 32 and Section 33 of the Securities and Exchange Act B.E. 2535 (1992) is required to comply with this Notification, unless otherwise stipulated by specific regulations in other Notifications.', 'The Capital Market Supervisory Board of the Kingdom of Thailand has issued the following regulations by virtue of section 16/6 and Section 89/27 of the Securities and Exchange Act B.E. 2535 (1992). The following Notifications are to come into effect from 1 January 2014. The securities issuer under Section 32 and Section 33 of the Securities and Exchange Act B.E. 2535 (1992) is required to comply with this Notification, unless otherwise stipulated by specific regulations in other Notifications.', 'The Capital Market Supervisory Board of the Kingdom of Thailand has issued the following regulations by virtue of section 16/6 and Section 89/27 of the Securities and Exchange Act B.E. 2535 (1992). The following Notifications are to come into effect from 1 January 2014. The securities issuer under Section 32 and Section 33 of the Securities and Exchange Act B.E. 2535 (1992) is required to comply with this Notification, unless otherwise stipulated by specific regulations in other Notifications.', 'Thailand', 'nature', 'in_force', '2014-01-01'::date, 'Thailand', 'https://www.carrotsandsticks.org/policies/177_2', ARRAY['guidance_frameworks', 'thailand', 'mandatory', 'disclosure', 'sdg15']::text[]) ON CONFLICT (id) DO NOTHING;
INSERT INTO regulations (id, title, formal_title, summary, description, full_description, region, category, status, effective_date, source_name, source_url, tags) VALUES ('074fb444-2fc2-5977-b285-190ac560e86c', 'Thailand Principles of Good Corporate Governance for Listed Companies', 'The Principles of Good Corporate Governance for Listed Companies, 2012', 'The Principles of Good Corporate Governance for Listed Companies is a series of principles and recommendations of best practice for companies listed on the Stock Exchange of Thailand (SET). These principles cover five key areas - the rights of shareholders, the equitable treatment of shareholders, the role of stakeholders, disclosure and transparency, and the responsibilities of the Board. These principles and recommendations are outlined under the concept of ''Comply or Explain''. The annual reports of listed companies must describe how these recommendations are being met and where they are not. In the latter case, the companies must thoroughly explain for what reasons they are not complying with the SET. In addition, companies are expected to make this information freely and conveniently available, i.e. online, for all potential stakeholders.', 'The Principles of Good Corporate Governance for Listed Companies is a series of principles and recommendations of best practice for companies listed on the Stock Exchange of Thailand (SET). These principles cover five key areas - the rights of shareholders, the equitable treatment of shareholders, the role of stakeholders, disclosure and transparency, and the responsibilities of the Board. These principles and recommendations are outlined under the concept of ''Comply or Explain''. The annual reports of listed companies must describe how these recommendations are being met and where they are not. In the latter case, the companies must thoroughly explain for what reasons they are not complying with the SET. In addition, companies are expected to make this information freely and conveniently available, i.e. online, for all potential stakeholders.', 'The Principles of Good Corporate Governance for Listed Companies is a series of principles and recommendations of best practice for companies listed on the Stock Exchange of Thailand (SET). These principles cover five key areas - the rights of shareholders, the equitable treatment of shareholders, the role of stakeholders, disclosure and transparency, and the responsibilities of the Board. These principles and recommendations are outlined under the concept of ''Comply or Explain''. The annual reports of listed companies must describe how these recommendations are being met and where they are not. In the latter case, the companies must thoroughly explain for what reasons they are not complying with the SET. In addition, companies are expected to make this information freely and conveniently available, i.e. online, for all potential stakeholders.', 'Thailand', 'climate', 'in_force', '2012-01-01'::date, 'Thailand', 'https://www.carrotsandsticks.org/policies/177_1', ARRAY['guidance_frameworks', 'thailand', 'sdg16', 'disclosure', 'sdg15', 'voluntary']::text[]) ON CONFLICT (id) DO NOTHING;
INSERT INTO regulations (id, title, formal_title, summary, description, full_description, region, category, status, effective_date, source_name, source_url, tags) VALUES ('2b009459-64af-5328-9e87-2a4d8ab81499', 'Thailand Occupational Safety, Health and Environment Act B.e. 2554', 'Occupational Safety, Health and Environment Act B.e. 2554 (a.d. 2011)', 'This Act contains certain provisions in relation to the restrictions on rights and liberties of the individual which are allowed under Section 29 together with Section 33, Section 41 and Section 43 of the Constitution of the Kingdom of Thailand.', 'This Act contains certain provisions in relation to the restrictions on rights and liberties of the individual which are allowed under Section 29 together with Section 33, Section 41 and Section 43 of the Constitution of the Kingdom of Thailand.', 'This Act contains certain provisions in relation to the restrictions on rights and liberties of the individual which are allowed under Section 29 together with Section 33, Section 41 and Section 43 of the Constitution of the Kingdom of Thailand.', 'Thailand', 'nature', 'in_force', '2011-01-01'::date, 'Thailand', 'https://www.carrotsandsticks.org/policies/177_16', ARRAY['sdg8', 'thailand', 'other sustainability policy', 'regulations', 'mandatory', 'sdg15', 'sdg3']::text[]) ON CONFLICT (id) DO NOTHING;
INSERT INTO regulations (id, title, formal_title, summary, description, full_description, region, category, status, effective_date, source_name, source_url, tags) VALUES ('2b3e00b6-c031-5733-94d5-203e294627af', 'Thailand Thai Labour Standards CSR for Thai Business TLS', 'Thai Labour Standards CSR for Thai Business TLS 8001-2010', 'This revised standard aims to be the operational guidelines for the establishments to provide appropriate protection for the workers by setting related policy for the effective implementation; to be a criteria for the establishments to audit and to declare themselves that they are in compliance with this standard; to be a criteria for certifying the establishments which imply this standard.', 'This revised standard aims to be the operational guidelines for the establishments to provide appropriate protection for the workers by setting related policy for the effective implementation; to be a criteria for the establishments to audit and to declare themselves that they are in compliance with this standard; to be a criteria for certifying the establishments which imply this standard.', 'This revised standard aims to be the operational guidelines for the establishments to provide appropriate protection for the workers by setting related policy for the effective implementation; to be a criteria for the establishments to audit and to declare themselves that they are in compliance with this standard; to be a criteria for certifying the establishments which imply this standard.', 'Thailand', 'social', 'in_force', '2010-01-01'::date, 'Thailand', 'https://www.carrotsandsticks.org/policies/177_3', ARRAY['sdg8', 'thailand', 'voluntary', 'disclosure', 'voluntary_frameworks']::text[]) ON CONFLICT (id) DO NOTHING;
INSERT INTO regulations (id, title, formal_title, summary, description, full_description, region, category, status, effective_date, source_name, source_url, tags) VALUES ('488b6e68-947d-5121-9b02-c329b3a94e65', 'Thailand Notification of Ministry of Industry. Subject: Registration', 'Notification of Ministry of Industry. Subject: Registration of Hazardous Substance, Issuance and Renewal of Registration Certificate Listed under Responsibility of Department of Industrial Works B.E. 2552 (2009)', 'This Notification from the Ministry of Industry concerns the procedures required when entities produce or import hazardous substances (types 2 and 3, as outlined in the Hazardous Substances Act). Those entities noted are required to apply for a registration of hazard substance using the WoAo/AoKo 1 form, provided in the annex of this Notification, which must be accompanied by the submission of a number of pieces of evidence, e.g. Safety Data Sheet (annexed in this Notification), laboratory analysis on the substance, photographic evidence. If approved, the registration is valid for six years. Changes to the original registration application can be made by using WoAo/AoKo 8 form, also within the annex, and if the registration is up for renewal, form WoAo/AoKo 4 is to be completed.', 'This Notification from the Ministry of Industry concerns the procedures required when entities produce or import hazardous substances (types 2 and 3, as outlined in the Hazardous Substances Act). Those entities noted are required to apply for a registration of hazard substance using the WoAo/AoKo 1 form, provided in the annex of this Notification, which must be accompanied by the submission of a number of pieces of evidence, e.g. Safety Data Sheet (annexed in this Notification), laboratory analysis on the substance, photographic evidence. If approved, the registration is valid for six years. Changes to the original registration application can be made by using WoAo/AoKo 8 form, also within the annex, and if the registration is up for renewal, form WoAo/AoKo 4 is to be completed.', 'This Notification from the Ministry of Industry concerns the procedures required when entities produce or import hazardous substances (types 2 and 3, as outlined in the Hazardous Substances Act). Those entities noted are required to apply for a registration of hazard substance using the WoAo/AoKo 1 form, provided in the annex of this Notification, which must be accompanied by the submission of a number of pieces of evidence, e.g. Safety Data Sheet (annexed in this Notification), laboratory analysis on the substance, photographic evidence. If approved, the registration is valid for six years. Changes to the original registration application can be made by using WoAo/AoKo 8 form, also within the annex, and if the registration is up for renewal, form WoAo/AoKo 4 is to be completed.', 'Thailand', 'climate', 'in_force', '2009-01-01'::date, 'Thailand', 'https://www.carrotsandsticks.org/policies/177_14', ARRAY['thailand', 'other sustainability policy', 'regulations', 'mandatory', 'sdg9']::text[]) ON CONFLICT (id) DO NOTHING;
INSERT INTO regulations (id, title, formal_title, summary, description, full_description, region, category, status, effective_date, source_name, source_url, tags) VALUES ('cc106b0f-68b5-5533-8196-b5c1af13b2cd', 'Thailand Notification of Ministry of Industry. Re: Preparation', 'Notification of Ministry of Industry. Re: Preparation of report on the study of prevention and mitigation measures on the impact to environmental quality and safety B.E. 2552', 'Any entity that wishes to request for a factory operation or factory expansion permit shall prepare a report on the prevention and mitigation of impacts to environmental quality and safety resulting from operations. Article 2 of the Notification details what must be included in the report for both the environmental and safety aspects. The finished reports shall be submitted with the permit application forms to the appropriate Provincial Industrial Office.', 'Any entity that wishes to request for a factory operation or factory expansion permit shall prepare a report on the prevention and mitigation of impacts to environmental quality and safety resulting from operations. Article 2 of the Notification details what must be included in the report for both the environmental and safety aspects. The finished reports shall be submitted with the permit application forms to the appropriate Provincial Industrial Office.', 'Any entity that wishes to request for a factory operation or factory expansion permit shall prepare a report on the prevention and mitigation of impacts to environmental quality and safety resulting from operations. Article 2 of the Notification details what must be included in the report for both the environmental and safety aspects. The finished reports shall be submitted with the permit application forms to the appropriate Provincial Industrial Office.', 'Thailand', 'climate', 'in_force', '2009-01-01'::date, 'Thailand', 'https://www.carrotsandsticks.org/policies/177_15', ARRAY['thailand', 'other sustainability policy', 'regulations', 'mandatory', 'sdg9']::text[]) ON CONFLICT (id) DO NOTHING;
INSERT INTO regulations (id, title, formal_title, summary, description, full_description, region, category, status, effective_date, source_name, source_url, tags) VALUES ('b1fa9fc4-9e9d-50f3-a5a2-546bd4e676be', 'Thailand Principles of Good Corporate Governance For Listed Companies', 'The Principles of Good Corporate Governance For Listed Companies', 'The Principles of Good Corporate Governance, published in 2006, is an updated version of the 15 principles announced in March 2002. More principles have been added to be comprehensive and comparable to the Principles of Corporate Governance of the Organisation for Economic Cooperation and Development (OECD). This version also includes the recommendations made by the World Bank in its Report on the Observance of Standards and Codes related to Thailand corporate governance (CG-ROSC).', 'The Principles of Good Corporate Governance, published in 2006, is an updated version of the 15 principles announced in March 2002. More principles have been added to be comprehensive and comparable to the Principles of Corporate Governance of the Organisation for Economic Cooperation and Development (OECD). This version also includes the recommendations made by the World Bank in its Report on the Observance of Standards and Codes related to Thailand corporate governance (CG-ROSC).', 'The Principles of Good Corporate Governance, published in 2006, is an updated version of the 15 principles announced in March 2002. More principles have been added to be comprehensive and comparable to the Principles of Corporate Governance of the Organisation for Economic Cooperation and Development (OECD). This version also includes the recommendations made by the World Bank in its Report on the Observance of Standards and Codes related to Thailand corporate governance (CG-ROSC).', 'Thailand', 'climate', 'in_force', '2006-01-01'::date, 'Thailand', 'https://www.carrotsandsticks.org/policies/177_4', ARRAY['guidance_frameworks', 'thailand', 'sdg17', 'sdg16', 'disclosure', 'sdg15', 'voluntary']::text[]) ON CONFLICT (id) DO NOTHING;
INSERT INTO regulations (id, title, formal_title, summary, description, full_description, region, category, status, effective_date, source_name, source_url, tags) VALUES ('0fb1d5af-b869-5005-96e6-a4027ac1c64a', 'Thailand Ministerial Regulation Re: Criteria, procedure and schedule', 'The Ministerial Regulation Re: Criteria, procedure and schedule for submission and recording of data on energy conservation B.E. 2547 (2004)', 'This Regulation is applicable to designated factories and buildings, as determined in Energy Conservation Promotion Act B.E. 2535 (1992). Designated factory owners shall collect data on production, energy consumption and energy conservation, and submit this using the BorPorRor.1 form. While designated building owners shall collect data on both the latter two metrics and on building utilization also, and submit this using the BorPorAor.1 form. Monthly data from January to June and from July to December is to be submitted in the following July and January, respectively. Submissions of the data shall be made to the Department of Alternative Energy Development and Efficiency.', 'This Regulation is applicable to designated factories and buildings, as determined in Energy Conservation Promotion Act B.E. 2535 (1992). Designated factory owners shall collect data on production, energy consumption and energy conservation, and submit this using the BorPorRor.1 form. While designated building owners shall collect data on both the latter two metrics and on building utilization also, and submit this using the BorPorAor.1 form. Monthly data from January to June and from July to December is to be submitted in the following July and January, respectively. Submissions of the data shall be made to the Department of Alternative Energy Development and Efficiency.', 'This Regulation is applicable to designated factories and buildings, as determined in Energy Conservation Promotion Act B.E. 2535 (1992). Designated factory owners shall collect data on production, energy consumption and energy conservation, and submit this using the BorPorRor.1 form. While designated building owners shall collect data on both the latter two metrics and on building utilization also, and submit this using the BorPorAor.1 form. Monthly data from January to June and from July to December is to be submitted in the following July and January, respectively. Submissions of the data shall be made to the Department of Alternative Energy Development and Efficiency.', 'Thailand', 'climate', 'in_force', '2004-01-01'::date, 'Thailand', 'https://www.carrotsandsticks.org/policies/177_13', ARRAY['thailand', 'other sustainability policy', 'regulations', 'sdg7', 'mandatory', 'sdg12']::text[]) ON CONFLICT (id) DO NOTHING;
INSERT INTO regulations (id, title, formal_title, summary, description, full_description, region, category, status, effective_date, source_name, source_url, tags) VALUES ('12ad6ef3-c8e0-5fb5-8faf-8a9fdb3f7d3d', 'Thailand (Garuda Emblem) Notification of Ministry of Industry Re', '(Garuda Emblem) Notification of Ministry of Industry Re: Safety procedure in working environment B.E. 2546 (2003)', 'Chapter 4 of this Notification requires that working environments shall be subject to analysis on heat, light and noise levels. This information is to be compiled into an annual report on the working environment and shall be certified by a safety officer with certain levels of educational achievement (detailed in the Notification). The report is to be kept onsite to await inspection. Articles 12, 13, 14 and 15 of Chapter 4 of the Notification outline the time and conditions when these measurements are to be taken. The previous chapters of the Notification detail the legal limits on heat, light and noise levels that relevant factories (see Lists 1 and 2 of the annex) must abide by.', 'Chapter 4 of this Notification requires that working environments shall be subject to analysis on heat, light and noise levels. This information is to be compiled into an annual report on the working environment and shall be certified by a safety officer with certain levels of educational achievement (detailed in the Notification). The report is to be kept onsite to await inspection. Articles 12, 13, 14 and 15 of Chapter 4 of the Notification outline the time and conditions when these measurements are to be taken. The previous chapters of the Notification detail the legal limits on heat, light and noise levels that relevant factories (see Lists 1 and 2 of the annex) must abide by.', 'Chapter 4 of this Notification requires that working environments shall be subject to analysis on heat, light and noise levels. This information is to be compiled into an annual report on the working environment and shall be certified by a safety officer with certain levels of educational achievement (detailed in the Notification). The report is to be kept onsite to await inspection. Articles 12, 13, 14 and 15 of Chapter 4 of the Notification outline the time and conditions when these measurements are to be taken. The previous chapters of the Notification detail the legal limits on heat, light and noise levels that relevant factories (see Lists 1 and 2 of the annex) must abide by.', 'Thailand', 'climate', 'in_force', '2003-01-01'::date, 'Thailand', 'https://www.carrotsandsticks.org/policies/177_12', ARRAY['sdg4', 'guidance_frameworks', 'thailand', 'other sustainability policy', 'mandatory', 'sdg9']::text[]) ON CONFLICT (id) DO NOTHING;
INSERT INTO regulations (id, title, formal_title, summary, description, full_description, region, category, status, effective_date, source_name, source_url, tags) VALUES ('8e9552fc-520c-5421-acd7-3826c25c1346', 'Thailand (Garuda Emblem) Notification of Ministry of Industry B.E', '(Garuda Emblem) Notification of Ministry of Industry No. 3 B.E. 2542 (1999) Issued pursuant to the Factory Act B.E. 2535 (1992) Re: Safety Working Measure', 'This notification prescribes safety working conditions in factories.', 'This notification prescribes safety working conditions in factories.', 'This notification prescribes safety working conditions in factories.', 'Thailand', 'social', 'in_force', '1999-01-01'::date, 'Thailand', 'https://www.carrotsandsticks.org/policies/177_11', ARRAY['sdg8', 'thailand', 'other sustainability policy', 'regulations', 'mandatory', 'sdg9']::text[]) ON CONFLICT (id) DO NOTHING;
INSERT INTO regulations (id, title, formal_title, summary, description, full_description, region, category, status, effective_date, source_name, source_url, tags) VALUES ('887c86a8-eec3-5d63-ac50-5338645cfcd0', 'Thailand Best Practice Guidelines for Audit Committee (Bor.Jor./Ror.25-00)', 'Best Practice Guidelines for Audit Committee (Bor.Jor./Ror.25-00)', 'The Stock Exchange of Thailand (SET) has established these Best Practice Guidelines for Audit Committee in order to ensure understanding of the duties of the Audit Committee and the coordination among the Audit Committee, the internal auditor and the external auditor for their smooth and efficient performance of duties.', 'The Stock Exchange of Thailand (SET) has established these Best Practice Guidelines for Audit Committee in order to ensure understanding of the duties of the Audit Committee and the coordination among the Audit Committee, the internal auditor and the external auditor for their smooth and efficient performance of duties.', 'The Stock Exchange of Thailand (SET) has established these Best Practice Guidelines for Audit Committee in order to ensure understanding of the duties of the Audit Committee and the coordination among the Audit Committee, the internal auditor and the external auditor for their smooth and efficient performance of duties.', 'Thailand', 'nature', 'in_force', '1999-01-01'::date, 'Thailand', 'https://www.carrotsandsticks.org/policies/177_5', ARRAY['thailand', 'regulations', 'disclosure', 'sdg15', 'voluntary']::text[]) ON CONFLICT (id) DO NOTHING;
INSERT INTO regulations (id, title, formal_title, summary, description, full_description, region, category, status, effective_date, source_name, source_url, tags) VALUES ('ea1d5392-a03a-5a3b-8012-d417111d3b52', 'Thailand Code of Best Practice for Directors of Listed', 'Code of Best Practice for Directors of Listed Companies (Bor.Jor. 25-4-01)', 'The Stock Exchange of Thailand’s (SET) Code of Best Practice for Directors of Listed Companies is not a legal requirement but should be used as guidelines for all board members concerning their behaviour while holding such appointments. The SET believes that management under these guidelines should help ensure a high standard of best practice on behalf of the company and its shareholders. The code should also strengthen the confidence of the shareholders, investors, and other related parties in the management of the company.', 'The Stock Exchange of Thailand’s (SET) Code of Best Practice for Directors of Listed Companies is not a legal requirement but should be used as guidelines for all board members concerning their behaviour while holding such appointments. The SET believes that management under these guidelines should help ensure a high standard of best practice on behalf of the company and its shareholders. The code should also strengthen the confidence of the shareholders, investors, and other related parties in the management of the company.', 'The Stock Exchange of Thailand’s (SET) Code of Best Practice for Directors of Listed Companies is not a legal requirement but should be used as guidelines for all board members concerning their behaviour while holding such appointments. The SET believes that management under these guidelines should help ensure a high standard of best practice on behalf of the company and its shareholders. The code should also strengthen the confidence of the shareholders, investors, and other related parties in the management of the company.', 'Thailand', 'nature', 'in_force', '1999-01-01'::date, 'Thailand', 'https://www.carrotsandsticks.org/policies/177_6', ARRAY['thailand', 'regulations', 'disclosure', 'sdg15', 'voluntary']::text[]) ON CONFLICT (id) DO NOTHING;
INSERT INTO regulations (id, title, formal_title, summary, description, full_description, region, category, status, effective_date, source_name, source_url, tags) VALUES ('825d09d4-544d-5d60-a0c9-0dd6ac443a32', 'Thailand SET Code of Best Practice for Directors', 'The SET Code of Best Practice for Directors of Listed Companies (Bor.Jor/.Ror.26-00)', 'The Stock Exchange of Thailand’s (SET) Code of Best Practice for the Directors of Listed Companies’ are not a legal requirement but should be considered guidelines for all board members concerning their behaviour while holding such appointments. The SET believes that management under these guidelines should help ensure a high standard of best practice on behalf of the company and its shareholders. The Code should also strengthen the confidence of the shareholders, investors, and other related parties in the management of the company.', 'The Stock Exchange of Thailand’s (SET) Code of Best Practice for the Directors of Listed Companies’ are not a legal requirement but should be considered guidelines for all board members concerning their behaviour while holding such appointments. The SET believes that management under these guidelines should help ensure a high standard of best practice on behalf of the company and its shareholders. The Code should also strengthen the confidence of the shareholders, investors, and other related parties in the management of the company.', 'The Stock Exchange of Thailand’s (SET) Code of Best Practice for the Directors of Listed Companies’ are not a legal requirement but should be considered guidelines for all board members concerning their behaviour while holding such appointments. The SET believes that management under these guidelines should help ensure a high standard of best practice on behalf of the company and its shareholders. The Code should also strengthen the confidence of the shareholders, investors, and other related parties in the management of the company.', 'Thailand', 'nature'