INSERT INTO regulations (id, title, formal_title, summary, description, full_description, region, category, status, effective_date, source_name, source_url, tags) VALUES ('acbb9250-83ca-5f7b-b475-f7a43832f74d', 'Investment Code of the Togolese Republic', 'Law No. 2019-005 Relating to the Investment Code of the Togolese Republic, 2019', 'Togo''s 2019 Investment Code aims to attract foreign investment and boost economic growth. It offers incentives like tax breaks, customs exemptions, and land access to investors in priority sectors like tourism, agriculture, and manufacturing. The code also guarantees free movement of capital and protects investors'' rights.', 'Togo''s 2019 Investment Code aims to attract foreign investment and boost economic growth. It offers incentives like tax breaks, customs exemptions, and land access to investors in priority sectors like tourism, agriculture, and manufacturing. The code also guarantees free movement of capital and protects investors'' rights.', 'Togo''s 2019 Investment Code aims to attract foreign investment and boost economic growth. It offers incentives like tax breaks, customs exemptions, and land access to investors in priority sectors like tourism, agriculture, and manufacturing. The code also guarantees free movement of capital and protects investors'' rights.', 'Togo', 'nature', 'in_force', '2019-01-01'::date, 'Togo', 'https://www.carrotsandsticks.org/policies/195_1', ARRAY['togo', 'sdg2', 'regulations', 'sdg9', 'mandatory', 'disclosure', 'sdg15']::text[]) ON CONFLICT (id) DO NOTHING;
INSERT INTO regulations (id, title, formal_title, summary, description, full_description, region, category, status, effective_date, source_name, source_url, tags) VALUES ('baeeda58-bffc-5a10-bfac-71fc64810d55', 'Trinidad and Tobago Corporate Governance Code', 'Corporate Governance Code, 2013', 'The Code follows globally accepted best practices with specific consideration and much customization for the local economy and dynamics of the business society of Trinidad and Tobago. The objectives are to enhance business governance and performance, strengthen transparency and efficiency in the market, and improve the overall investment culture in Trinidad & Tobago. The Code is easy to understand, providing recommendations and guidelines for good corporate governance with a balance between costs and benefits of implementation. In this way, it provides the structure through which the company’s objectives are set along with the means of attaining them and monitoring performance.', 'The Code follows globally accepted best practices with specific consideration and much customization for the local economy and dynamics of the business society of Trinidad and Tobago. The objectives are to enhance business governance and performance, strengthen transparency and efficiency in the market, and improve the overall investment culture in Trinidad & Tobago. The Code is easy to understand, providing recommendations and guidelines for good corporate governance with a balance between costs and benefits of implementation. In this way, it provides the structure through which the company’s objectives are set along with the means of attaining them and monitoring performance.', 'The Code follows globally accepted best practices with specific consideration and much customization for the local economy and dynamics of the business society of Trinidad and Tobago. The objectives are to enhance business governance and performance, strengthen transparency and efficiency in the market, and improve the overall investment culture in Trinidad & Tobago. The Code is easy to understand, providing recommendations and guidelines for good corporate governance with a balance between costs and benefits of implementation. In this way, it provides the structure through which the company’s objectives are set along with the means of attaining them and monitoring performance.', 'Trinidad and Tobago', 'governance', 'in_force', '2013-01-01'::date, 'Trinidad and Tobago', 'https://www.carrotsandsticks.org/policies/178_2', ARRAY['regulations', 'mandatory', 'trinidad and tobago', 'sdg16', 'disclosure', 'sdg9']::text[]) ON CONFLICT (id) DO NOTHING;
INSERT INTO regulations (id, title, formal_title, summary, description, full_description, region, category, status, effective_date, source_name, source_url, tags) VALUES ('903e54ca-7329-50a4-8109-78c66f024e3b', 'Trinidad and Tobago Corporate Governance Guideline', 'Corporate Governance Guideline, 2007', 'The purposes of this Guideline are to ensure that (a) the Board of Directors and Senior Management of these institutions are fully cognizant of the need to adopt sound principles and practices for the internal governance of the institutions they oversee, and (b) institutions are aware of the factors considered by the Central Bank in assessing corporate governance practices.', 'The purposes of this Guideline are to ensure that (a) the Board of Directors and Senior Management of these institutions are fully cognizant of the need to adopt sound principles and practices for the internal governance of the institutions they oversee, and (b) institutions are aware of the factors considered by the Central Bank in assessing corporate governance practices.', 'The purposes of this Guideline are to ensure that (a) the Board of Directors and Senior Management of these institutions are fully cognizant of the need to adopt sound principles and practices for the internal governance of the institutions they oversee, and (b) institutions are aware of the factors considered by the Central Bank in assessing corporate governance practices.', 'Trinidad and Tobago', 'governance', 'in_force', '2007-01-01'::date, 'Trinidad and Tobago', 'https://www.carrotsandsticks.org/policies/178_1', ARRAY['guidance_frameworks', 'other sustainability policy', 'trinidad and tobago', 'sdg16', 'voluntary']::text[]) ON CONFLICT (id) DO NOTHING;
INSERT INTO regulations (id, title, formal_title, summary, description, full_description, region, category, status, effective_date, source_name, source_url, tags) VALUES ('28a0757d-5978-5a15-8e97-6805aa935998', 'Tunisia Your guide to ESG reporting', 'Your guide to ESG reporting, 2021', 'This guide proposes a matrix of indicators for a progressive approach to extra-financial reporting on environmental, social and governance (ESG) considerations. It is based on the Global Reporting Initiative (GRI) standard, the recommendations of the World Federation of Exchanges (WFE), the 17 Sustainable Development Goals (SDGs) adopted by the United Nations.', 'This guide proposes a matrix of indicators for a progressive approach to extra-financial reporting on environmental, social and governance (ESG) considerations. It is based on the Global Reporting Initiative (GRI) standard, the recommendations of the World Federation of Exchanges (WFE), the 17 Sustainable Development Goals (SDGs) adopted by the United Nations.', 'This guide proposes a matrix of indicators for a progressive approach to extra-financial reporting on environmental, social and governance (ESG) considerations. It is based on the Global Reporting Initiative (GRI) standard, the recommendations of the World Federation of Exchanges (WFE), the 17 Sustainable Development Goals (SDGs) adopted by the United Nations.', 'Tunisia', 'climate', 'in_force', '2021-01-01'::date, 'Tunisia', 'https://www.carrotsandsticks.org/policies/179_2', ARRAY['mandatory', 'sdg16', 'mandatory_regulations', 'disclosure', 'tunisia']::text[]) ON CONFLICT (id) DO NOTHING;
INSERT INTO regulations (id, title, formal_title, summary, description, full_description, region, category, status, effective_date, source_name, source_url, tags) VALUES ('18cb8d8e-8c59-5fb8-9e90-7d916588468b', 'Tunisia Guide to Good Practices of Governance of Governance', 'Guide to Good Practices of Governance of Governance Tunisian Companies, 2012', 'This Guide presents the major recommendations relating to the management and control of companies (corporate governance) and includes international standards, inspired in particular by the principles of corporate governance of the OECD, and national standards recognized as necessary for the proper conduct and responsible business management.', 'This Guide presents the major recommendations relating to the management and control of companies (corporate governance) and includes international standards, inspired in particular by the principles of corporate governance of the OECD, and national standards recognized as necessary for the proper conduct and responsible business management.', 'This Guide presents the major recommendations relating to the management and control of companies (corporate governance) and includes international standards, inspired in particular by the principles of corporate governance of the OECD, and national standards recognized as necessary for the proper conduct and responsible business management.', 'Tunisia', 'governance', 'in_force', '2012-01-01'::date, 'Tunisia', 'https://www.carrotsandsticks.org/policies/179_1', ARRAY['other sustainability policy', 'regulations', 'mandatory', 'sdg16', 'tunisia']::text[]) ON CONFLICT (id) DO NOTHING;
INSERT INTO regulations (id, title, formal_title, summary, description, full_description, region, category, status, effective_date, source_name, source_url, tags) VALUES ('e9bf0bc9-cb94-547a-b837-4cad7e201a64', 'Tunisia Code of Best Practice of Corporate Governance', 'Code of Best Practice of Corporate Governance, 2008', 'This Guide of best corporate governance practices for Tunisian corporations presents the major recommendations related to corporate management and control. It also includes international and national standards known for company’s good conduct and responsible management. The Guide aims at making Tunisian corporate governance system more transparent and intelligible. Its ultimate objective is to promote the trust in Tunisian corporations’ management and control of national and international investors, customers, employees and the community.', 'This Guide of best corporate governance practices for Tunisian corporations presents the major recommendations related to corporate management and control. It also includes international and national standards known for company’s good conduct and responsible management. The Guide aims at making Tunisian corporate governance system more transparent and intelligible. Its ultimate objective is to promote the trust in Tunisian corporations’ management and control of national and international investors, customers, employees and the community.', 'This Guide of best corporate governance practices for Tunisian corporations presents the major recommendations related to corporate management and control. It also includes international and national standards known for company’s good conduct and responsible management. The Guide aims at making Tunisian corporate governance system more transparent and intelligible. Its ultimate objective is to promote the trust in Tunisian corporations’ management and control of national and international investors, customers, employees and the community.', 'Tunisia', 'governance', 'in_force', '2008-01-01'::date, 'Tunisia', 'https://www.carrotsandsticks.org/policies/179_3', ARRAY['other sustainability policy', 'regulations', 'sdg11', 'sdg16', 'tunisia', 'voluntary']::text[]) ON CONFLICT (id) DO NOTHING;
INSERT INTO regulations (id, title, formal_title, summary, description, full_description, region, category, status, effective_date, source_name, source_url, tags) VALUES ('97dda773-3cca-5c44-bb08-c848877b0beb', 'Turkey In the Future to Exist For Companies Sustainability', 'In the Future to Exist For Companies Sustainability Guide', 'Borsa Istanbul is proud to present this guide, which is based on ESG factors and the Global Reporting Initiative and aims to provide a guiding framework for companies.', 'Borsa Istanbul is proud to present this guide, which is based on ESG factors and the Global Reporting Initiative and aims to provide a guiding framework for companies.', 'Borsa Istanbul is proud to present this guide, which is based on ESG factors and the Global Reporting Initiative and aims to provide a guiding framework for companies.', 'Turkey', 'climate', 'in_force', '2020-01-01'::date, 'Turkey', 'https://www.carrotsandsticks.org/policies/180_13', ARRAY['turkey', 'sdg13', 'other sustainability policy', 'regulations', 'mandatory', 'sdg16', 'sdg12']::text[]) ON CONFLICT (id) DO NOTHING;
INSERT INTO regulations (id, title, formal_title, summary, description, full_description, region, category, status, effective_date, source_name, source_url, tags) VALUES ('62efb089-0d75-5198-b0b0-5f5cd6bd0935', 'Turkey Sustainability Guidebook for Companies', 'Sustainability Guidebook for Companies, 2020', 'The guide covers key areas such as corporate governance, environmental impact, and social responsibility. It provides a framework for companies to assess their sustainability practices and improve their sustainability reporting. The guide also includes a list of indicators that companies can use to measure their progress in each area, as well as guidelines on how to disclose sustainability information to investors and other stakeholders. While compliance with the guide is voluntary, it is expected that companies will increasingly adopt sustainable practices and reporting as investors and customers demand greater transparency and responsibility.', 'The guide covers key areas such as corporate governance, environmental impact, and social responsibility. It provides a framework for companies to assess their sustainability practices and improve their sustainability reporting. The guide also includes a list of indicators that companies can use to measure their progress in each area, as well as guidelines on how to disclose sustainability information to investors and other stakeholders. While compliance with the guide is voluntary, it is expected that companies will increasingly adopt sustainable practices and reporting as investors and customers demand greater transparency and responsibility.', 'The guide covers key areas such as corporate governance, environmental impact, and social responsibility. It provides a framework for companies to assess their sustainability practices and improve their sustainability reporting. The guide also includes a list of indicators that companies can use to measure their progress in each area, as well as guidelines on how to disclose sustainability information to investors and other stakeholders. While compliance with the guide is voluntary, it is expected that companies will increasingly adopt sustainable practices and reporting as investors and customers demand greater transparency and responsibility.', 'Turkey', 'climate', 'in_force', '2020-01-01'::date, 'Turkey', 'https://www.carrotsandsticks.org/policies/180_18', ARRAY['turkey', 'regulations', 'mandatory', 'sdg16', 'disclosure']::text[]) ON CONFLICT (id) DO NOTHING;
INSERT INTO regulations (id, title, formal_title, summary, description, full_description, region, category, status, effective_date, source_name, source_url, tags) VALUES ('c547116f-47f8-5f91-9f87-24be5db8d310', 'CDP Climate Change and Water Report 2018. Turkey Editiion', 'CDP Climate Change and Water Report 2018. Turkey Editiion', 'CDP Turkey, on its nineth year for the Climate Change Program and fourth year for the Water Program, has released the CDP Turkey 2018 Climate Change and Water Report. The report constitutes of the responses of responding companies to CDP in Turkey; data and findings that demonstrate and analyse the actions taken by companies on the issues of Climate Change and Water Security, their goals and engagement strategies, and also how they are managing their climate and water-related risks.', 'CDP Turkey, on its nineth year for the Climate Change Program and fourth year for the Water Program, has released the CDP Turkey 2018 Climate Change and Water Report. The report constitutes of the responses of responding companies to CDP in Turkey; data and findings that demonstrate and analyse the actions taken by companies on the issues of Climate Change and Water Security, their goals and engagement strategies, and also how they are managing their climate and water-related risks.', 'CDP Turkey, on its nineth year for the Climate Change Program and fourth year for the Water Program, has released the CDP Turkey 2018 Climate Change and Water Report. The report constitutes of the responses of responding companies to CDP in Turkey; data and findings that demonstrate and analyse the actions taken by companies on the issues of Climate Change and Water Security, their goals and engagement strategies, and also how they are managing their climate and water-related risks.', 'Turkey', 'climate', 'in_force', '2018-01-01'::date, 'Turkey', 'https://www.carrotsandsticks.org/policies/180_5', ARRAY['turkey', 'sdg13', 'other sustainability policy', 'mandatory', 'sdg6', 'mandatory_regulations']::text[]) ON CONFLICT (id) DO NOTHING;
INSERT INTO regulations (id, title, formal_title, summary, description, full_description, region, category, status, effective_date, source_name, source_url, tags) VALUES ('dfb72d00-278d-5054-a5c0-02be5dec96a2', 'Turkey Sustainability Guidelines for Companies', 'Sustainability Guidelines for Companies, 2015', 'The guidebook looks to introduce listed companies to the concepts and trends surrounding sustainability and corporate responsibility. It provides a thorough background overview and proceeds to build a business case for why it is beneficial/ responsible for companies to compile data and produce sustainability reports as part of their annual report. BIST 30 have been assessed in 2014 and BIST 50 constituent companies in 2015. Starting from 2016, volunteer companies from BIST 100 are added to the list of companies to be assessed “The assessment list” is revised annually and announced by Borsa İstanbul in December.', 'The guidebook looks to introduce listed companies to the concepts and trends surrounding sustainability and corporate responsibility. It provides a thorough background overview and proceeds to build a business case for why it is beneficial/ responsible for companies to compile data and produce sustainability reports as part of their annual report. BIST 30 have been assessed in 2014 and BIST 50 constituent companies in 2015. Starting from 2016, volunteer companies from BIST 100 are added to the list of companies to be assessed “The assessment list” is revised annually and announced by Borsa İstanbul in December.', 'The guidebook looks to introduce listed companies to the concepts and trends surrounding sustainability and corporate responsibility. It provides a thorough background overview and proceeds to build a business case for why it is beneficial/ responsible for companies to compile data and produce sustainability reports as part of their annual report. BIST 30 have been assessed in 2014 and BIST 50 constituent companies in 2015. Starting from 2016, volunteer companies from BIST 100 are added to the list of companies to be assessed “The assessment list” is revised annually and announced by Borsa İstanbul in December.', 'Turkey', 'climate', 'in_force', '2015-01-01'::date, 'Turkey', 'https://www.carrotsandsticks.org/policies/180_14', ARRAY['turkey', 'guidance_frameworks', 'sdg13', 'other sustainability policy', 'sdg16', 'sdg12', 'voluntary']::text[]) ON CONFLICT (id) DO NOTHING;
