INSERT INTO regulations (id, title, formal_title, summary, description, full_description, region, category, status, effective_date, source_name, source_url, tags) VALUES ('db2e996a-fd58-5fce-9d02-d74789e3d902', 'Turkey II-17.1 Communiqué on Corporate Governance', 'II-17.1 Communiqué on Corporate Governance', 'The purpose and scope of this Communiqué is to determine the principles of corporate governance and principles and procedures on related party transactions, which shall be applied by corporations.', 'The purpose and scope of this Communiqué is to determine the principles of corporate governance and principles and procedures on related party transactions, which shall be applied by corporations.', 'The purpose and scope of this Communiqué is to determine the principles of corporate governance and principles and procedures on related party transactions, which shall be applied by corporations.', 'Turkey', 'governance', 'in_force', '2014-01-01'::date, 'Turkey', 'https://www.carrotsandsticks.org/policies/180_2', ARRAY['turkey', 'other sustainability policy', 'regulations', 'mandatory', 'sdg16']::text[]) ON CONFLICT (id) DO NOTHING;
INSERT INTO regulations (id, title, formal_title, summary, description, full_description, region, category, status, effective_date, source_name, source_url, tags) VALUES ('8da801a9-ab72-5382-8fac-ac7dc30d4b45', 'Turkey Monitoring and Reporting of Greenhouse Gas Emissions', 'Monitoring and Reporting of Greenhouse Gas Emissions', 'It regulates the procedures and principles regarding the monitoring and reporting of greenhouse gas emissions and related activity data within the scope of the Regulation on the Monitoring of Emissions.', 'It regulates the procedures and principles regarding the monitoring and reporting of greenhouse gas emissions and related activity data within the scope of the Regulation on the Monitoring of Emissions.', 'It regulates the procedures and principles regarding the monitoring and reporting of greenhouse gas emissions and related activity data within the scope of the Regulation on the Monitoring of Emissions.', 'Turkey', 'climate', 'in_force', '2014-01-01'::date, 'Turkey', 'https://www.carrotsandsticks.org/policies/180_3', ARRAY['turkey', 'sdg13', 'other sustainability policy', 'sdg11', 'mandatory', 'mandatory_regulations']::text[]) ON CONFLICT (id) DO NOTHING;
INSERT INTO regulations (id, title, formal_title, summary, description, full_description, region, category, status, effective_date, source_name, source_url, tags) VALUES ('423dabbe-66dd-5a4b-97ea-4332a4ce95f7', 'Turkey Bist Sustainability Index Ground Rules', 'Bist Sustainability Index Ground Rules', 'The purpose of BIST Sustainability Index (the index hereafter) is to create an index whose constituents are selected by the companies whose corporate sustainability performance is high level among the listed companies in Borsa İstanbul and in extent to increase awareness, know-how and hand-on practice of the companies about sustainability in Turkey, especially the ones listed in Borsa İstanbul.', 'The purpose of BIST Sustainability Index (the index hereafter) is to create an index whose constituents are selected by the companies whose corporate sustainability performance is high level among the listed companies in Borsa İstanbul and in extent to increase awareness, know-how and hand-on practice of the companies about sustainability in Turkey, especially the ones listed in Borsa İstanbul.', 'The purpose of BIST Sustainability Index (the index hereafter) is to create an index whose constituents are selected by the companies whose corporate sustainability performance is high level among the listed companies in Borsa İstanbul and in extent to increase awareness, know-how and hand-on practice of the companies about sustainability in Turkey, especially the ones listed in Borsa İstanbul.', 'Turkey', 'climate', 'in_force', '2014-01-01'::date, 'Turkey', 'https://www.carrotsandsticks.org/policies/180_7', ARRAY['turkey', 'sdg13', 'other sustainability policy', 'regulations', 'mandatory', 'sdg16', 'sdg12']::text[]) ON CONFLICT (id) DO NOTHING;
